    "Thermal Equilibrium": "Kesetimbangan Termal",
    "The Zeroth Law describes thermal equilibrium between systems and provides the foundation for defining and measuring temperature.": "Hukum 0 menjelaskan kesetimbangan termal antarsistem dan menjadi dasar pendefinisian serta pengukuran temperatur.",
