    "Thermal equilibrium occurs when two systems have the same temperature and there is no net heat transfer between them. Although formulated after the First and Second Laws, it is called the Zeroth Law because this idea is more fundamental.": "Kesetimbangan termal terjadi ketika dua sistem memiliki temperatur yang sama sehingga tidak terjadi perpindahan kalor bersih. Walaupun dirumuskan setelah Hukum I dan II, konsep ini disebut Hukum 0 karena lebih mendasar.",
    "Key Concepts": "Konsep Penting",
