    "Moving heat from cold to hot requires an additional process and an energy input, as in a refrigerator.": "Memindahkan kalor dari benda dingin ke benda panas memerlukan proses tambahan dan masukan energi, seperti pada kulkas.",
    "Entropy (S)": "Entropi (S)",
    "Entropy is a state quantity used to explain the direction of processes and the irreversibility of a system. For reversible heat transfer at a constant absolute temperature:": "Entropi merupakan besaran keadaan yang menjelaskan arah proses dan tingkat irreversibilitas sistem. Untuk perpindahan kalor reversibel pada temperatur mutlak tetap:",
    "Change in entropy (J/K)": "Perubahan entropi (J/K)",
