    "For an isolated system, the total entropy cannot decrease:": "Pada sistem terisolasi, entropi total tidak dapat berkurang:",
    "Reversible and Irreversible": "Reversibel dan Irreversibel",
    "Reversible:": "Reversibel:",
    "an ideal process that can be reversed while returning both the system and surroundings to their original states with no net change.": "proses ideal yang dapat dibalik sehingga sistem dan lingkungan kembali ke keadaan semula tanpa perubahan bersih.",
    "Irreversible:": "Irreversibel:",
    "a real process that cannot be fully reversed without leaving a change in the surroundings. Most everyday processes are irreversible.": "proses nyata yang tidak dapat dibalik sepenuhnya tanpa menyisakan perubahan pada lingkungan. Sebagian besar proses sehari-hari bersifat irreversibel.",
    "Everyday Example": "Contoh Sehari-hari",
    "Hot coffee cools on a table.": "Kopi panas mendingin di atas meja.",
    "Heat transfers from the coffee to the cooler surroundings; its temperature decreases toward ambient temperature.": "Kalor berpindah dari kopi ke lingkungan yang lebih dingin sehingga temperaturnya turun mendekati temperatur lingkungan.",
    "Cooling happens spontaneously. Cold coffee does not spontaneously become hotter by extracting heat from an even colder environment. This reveals the natural direction of heat flow.": "Pendinginan berlangsung secara spontan. Kopi dingin tidak tiba-tiba menjadi lebih panas dengan mengambil kalor dari lingkungan yang lebih dingin. Hal ini menunjukkan arah alami aliran kalor.",
    "Entropy Example": "Contoh Entropi",
