    "Discover the entropy limit of a perfect crystal as its temperature approaches 0 K.": "Pelajari batas entropi kristal sempurna saat temperaturnya mendekati 0 K.",
    "Approaching Absolute Zero": "Mendekati Nol Absolut",
    "The Third Law describes how entropy behaves as temperature approaches absolute zero. Its statement for a perfect crystal is:": "Hukum III menjelaskan perilaku entropi ketika temperatur mendekati nol absolut. Pernyataan untuk kristal sempurna adalah:",
    "The entropy of a perfect crystal approaches zero as its temperature approaches 0 K.": "Entropi kristal sempurna mendekati nol ketika temperatur mendekati 0 K.",
    "This relation applies to a perfect crystal.": "Hubungan ini berlaku untuk kristal sempurna.",
    "As a perfect crystal approaches this temperature, its thermal state becomes highly ordered and it has a single possible ground state.": "Saat kristal sempurna mendekati temperatur ini, keadaan termalnya semakin teratur dan hanya memiliki satu kemungkinan keadaan dasar.",
    "Boltzmann Interpretation": "Penafsiran Boltzmann",
    "The microscopic interpretation uses the Boltzmann equation (the source document denotes the number of microstates by W):": "Penjelasan mikroskopis menggunakan persamaan Boltzmann (dokumen sumber melambangkan jumlah keadaan mikro dengan W):",
    "Entropy (J/K)": "Entropi (J/K)",
