    "9 categories": "9 kategori",
    "Temperature values are absolute readings, not temperature differences; values below 0 K are rejected. Other categories also accept signed values for changes or mathematical calculations.": "Nilai temperatur merupakan pembacaan suhu, bukan selisih suhu; nilai di bawah 0 K tidak diperbolehkan. Kategori lain juga menerima nilai positif dan negatif untuk perubahan besaran atau perhitungan matematis.",
    "Definitions: US liquid gallon; mechanical horsepower; thermochemical calorie (4.184 J); international-table BTU. Results display up to 15 significant digits; the conversion itself is not rounded.": "Definisi satuan: galon cair AS; daya kuda mekanis; kalori termokimia (4,184 J); BTU tabel internasional. Hasil ditampilkan hingga 15 angka penting; nilai konversi tidak dibulatkan selama perhitungan.",
