    "The PDF could not be read. Save it as a PDF containing text, or use DOCX.": "PDF tidak dapat dibaca. Simpan ulang sebagai PDF dengan teks, atau gunakan DOCX.",
    "No PDF text was found. For scanned or photographed documents, run OCR using Google Drive, Word, or a scanning app; then save as a PDF containing text or as DOCX.": "Teks PDF tidak ditemukan. Jika dokumen hasil scan atau foto, jalankan OCR melalui Google Drive, Word, atau aplikasi pemindai; lalu simpan sebagai PDF dengan teks atau DOCX.",
    "There is too little text. Use a DOCX file with text paragraphs; images are not converted to text.": "Teks materi terlalu sedikit. Gunakan DOCX dengan paragraf teks; gambar tidak diubah menjadi teks.",
