    "Fix the following before saving:": "Perbaiki bagian berikut sebelum menyimpan:",
    "The request failed. Check your connection and Supabase configuration, then try again.": "Permintaan tidak berhasil. Coba lagi setelah memeriksa koneksi dan konfigurasi Supabase.",
