    "Loading your cloud library…": "Memuat koleksi cloud…",
    "No question sets yet. Save your first draft to the cloud.": "Belum ada set soal. Simpan draf pertamamu ke cloud.",
    "The local draft of this set is open. Your changes are preserved; the cloud library does not overwrite the draft.": "Draf lokal set ini dibuka. Perubahanmu tetap tersimpan; koleksi cloud tidak menimpa draf.",
    "The cloud question set is open as an editable draft.": "Set soal cloud dibuka sebagai draf yang bisa diedit.",
    "Sign in before saving to the cloud.": "Login terlebih dahulu untuk menyimpan ke cloud.",
