    "The cloud question set was deleted. Your local draft is still available.": "Set soal cloud dihapus. Draf lokal tetap tersedia.",
    "All questions are complete and ready to save to the cloud.": "Semua soal sudah lengkap dan siap disimpan ke cloud.",
    "Please enter a room code.": "Masukkan kode ruang kuis.",
