    "Room code must contain 6 digits.": "Kode ruang harus terdiri dari 6 digit.",
    "This quiz has already started or finished.": "Kuis ini sudah dimulai atau selesai.",
    "This nickname is already used in this room.": "Nama panggilan ini sudah digunakan di ruang ini.",
    "Failed to join room.": "Gagal bergabung ke ruang kuis.",
    "Room information not found.": "Informasi ruang kuis tidak ditemukan.",
    "Starting Quiz...": "Memulai kuis...",
    "Failed to start quiz.": "Gagal memulai kuis.",
    "Quiz is starting...": "Kuis akan dimulai...",
    "Player not found": "Peserta tidak ditemukan",
    "Player left this quiz": "Peserta meninggalkan kuis ini",
    "All questions submitted": "Semua jawaban telah dikirim",
    "Invalid custom question snapshot.": "Data soal kustom tidak valid.",
    "Pressure remains constant throughout the process. Adding heat increases the temperature and changes the gas volume.": "Tekanan tetap selama proses. Kalor yang ditambahkan meningkatkan suhu dan mengubah volume gas.",
    "Volume remains constant throughout the process. Adding heat increases both the temperature and the gas pressure.": "Volume tetap selama proses. Kalor yang ditambahkan meningkatkan suhu dan tekanan gas.",
    "Temperature remains constant throughout the process. Changing the volume changes the pressure. The heat absorbed equals the work done by the gas.": "Suhu tetap selama proses. Perubahan volume mengubah tekanan. Kalor yang diterima sama dengan usaha yang dilakukan gas.",
    "There is no heat exchange with the surroundings. Q = 0, so changes in internal energy come from work.": "Tidak ada pertukaran kalor dengan lingkungan. Q = 0, sehingga perubahan energi dalam berasal dari usaha.",
    "The hot temperature must be higher than the cold temperature.": "Temperatur panas harus lebih tinggi daripada temperatur dingin.",
    "The temperature is very close to absolute zero. Thermal motion is very small and the entropy of a perfect crystal approaches zero.": "Temperatur sangat mendekati nol absolut. Gerakan termal partikel sangat kecil dan entropi kristal sempurna mendekati nol.",
    "The system is at a very low temperature. Particles undergo only small vibrations around their equilibrium positions.": "Sistem berada pada temperatur yang sangat rendah. Partikel hanya mengalami getaran kecil di sekitar posisi keseimbangannya.",
    "As temperature decreases, thermal motion decreases and crystal order increases.": "Ketika temperatur semakin rendah, gerakan termal partikel berkurang dan keteraturan kristal meningkat.",
    "At moderate temperatures, particles continue to vibrate around their equilibrium positions.": "Temperatur sedang menyebabkan partikel tetap bergetar di sekitar posisi keseimbangannya.",
    "Energy Limit": "Batas energi",
    "Work Done": "Usaha yang dilakukan",
    "TA = TB = TC. All three systems are in thermal equilibrium.": "TA = TB = TC. Ketiga sistem berada dalam kesetimbangan termal.",
    "There is no net heat transfer. Particles remain in motion.": "Tidak ada perpindahan kalor bersih. Partikel tetap bergerak.",
    "Heat flows from the hotter System A to the colder System B.": "Kalor berpindah dari Sistem A yang lebih panas menuju Sistem B yang lebih dingin.",
    "Heat flows from the hotter System B to the colder System A.": "Kalor berpindah dari Sistem B yang lebih panas menuju Sistem A yang lebih dingin.",
    "Systems A and B have the same temperature.": "Temperatur Sistem A dan B sama.",
    "added": "Ditambahkan",
    "Not added": "Belum ditambahkan",
    "Project Contributor / Blacksmith": "Kontributor Proyek / Pandai Besi",
    "API & System Development": "Pengembangan API & Sistem",
    "Research & Development": "Riset & Pengembangan",
    "UI / UX Designer, Frontend Developer": "Desainer UI / UX, Pengembang Frontend",
    "A collaborative contributor in THERMPYX who helps turn the team's ideas into an interactive learning experience. THERMPYX became one of his first opportunities to explore digital learning media.": "Seorang anggota kolaboratif dalam THERMPYX yang membantu mewujudkan ide tim menjadi pengalaman belajar interaktif. THERMPYX menjadi salah satu kesempatan pertamanya untuk mengeksplorasi media pembelajaran digital.",
    "Focused on the technical and logical side of THERMPYX. Through this project, John explores how system logic and web technology can support an interactive educational experience.": "Berfokus pada sisi teknis dan logika THERMPYX. Melalui proyek ini, John mengeksplorasi bagaimana logika sistem dan teknologi web dapat mendukung pengalaman pembelajaran interaktif.",
    "Contributes to THERMPYX through exploration, research, and continuous refinement. The project provides an opportunity to experience how scientific ideas can become interactive learning media.": "Berkontribusi dalam THERMPYX melalui eksplorasi, riset, dan penyempurnaan berkelanjutan. Proyek ini menjadi kesempatan untuk melihat bagaimana ide sains dapat diubah menjadi media pembelajaran interaktif.",
    "Focused on visual experience and interface design. Through THERMPYX, Naspad explores how layout, interaction, and visual identity can make scientific learning clearer and more engaging.": "Berfokus pada pengalaman visual dan desain antarmuka. Melalui THERMPYX, Naspad mengeksplorasi bagaimana layout, interaksi, dan identitas visual dapat membuat pembelajaran sains lebih jelas dan menarik.",
    "Joined the first four-person THERMPYX development team.": "Bergabung dalam tim pengembang pertama THERMPYX yang terdiri dari empat orang.",
    "Contributed to the collaborative development of the team's first interactive learning media project.": "Berkontribusi dalam pengembangan kolaboratif proyek media pembelajaran interaktif pertama tim.",
    "Continues exploring technology, teamwork, and digital learning media.": "Terus mengeksplorasi teknologi, kerja sama tim, dan media pembelajaran digital.",
    "Started exploring the technical foundation behind THERMPYX.": "Mulai mengeksplorasi fondasi teknis di balik THERMPYX.",
    "Contributed to system-oriented development and project logic.": "Berkontribusi pada pengembangan sistem dan logika proyek.",
    "Continues developing technical skills through future digital projects.": "Terus mengembangkan kemampuan teknis melalui proyek digital berikutnya.",
    "Participated in exploring ideas and learning content for THERMPYX.": "Berpartisipasi dalam eksplorasi ide dan konten pembelajaran THERMPYX.",
    "Supported development through analysis and continuous refinement.": "Mendukung pengembangan melalui analisis dan penyempurnaan berkelanjutan.",
    "Continues learning from the team's first digital media development experience.": "Terus belajar dari pengalaman pertama tim dalam pengembangan media digital.",
    "Explored visual direction and interface ideas for THERMPYX.": "Mengeksplorasi arah visual dan ide antarmuka untuk THERMPYX.",
    "Contributed to an interface that feels modern and connected to the project's identity.": "Berkontribusi dalam menciptakan antarmuka modern yang sesuai dengan identitas proyek.",
    "Continues exploring UI/UX and creative digital experiences.": "Terus mengeksplorasi UI/UX dan pengalaman digital kreatif.",
