    "Join a room to start.": "Bergabunglah ke ruang kuis untuk memulai.",
    "Unable to load room.": "Tidak dapat memuat ruang kuis.",
    "Added": "Ditambahkan",
    "A collaborative team of four students developing their first interactive thermodynamics learning website.": "Tim kolaboratif yang terdiri dari empat mahasiswa yang mengembangkan website pembelajaran termodinamika interaktif pertama mereka.",
