    "Diagram tekanan-volume membantu menggambarkan proses termodinamika:": "A pressure-volume diagram helps illustrate thermodynamic processes:",
    "Isobarik: garis horizontal (tekanan tetap).": "Isobaric: horizontal line (constant pressure).",
    "Isokhorik: garis vertikal (volume tetap).": "Isochoric: vertical line (constant volume).",
