    "TERMODINAMIKA • KALOR & TEMPERATUR": "THERMODYNAMICS • HEAT & TEMPERATURE",
    "Jelajahi pengaruh perpindahan kalor terhadap temperatur dan gerak partikel.": "Explore how heat transfer affects temperature and the motion of particles.",
