    "KONSEP DASAR": "FUNDAMENTAL CONCEPTS",
    "Work & Energy dalam Termodinamika": "Work & Energy in Thermodynamics",
    "A. Konsep Work dalam Termodinamika": "A. Work in Thermodynamics",
    "Dalam termodinamika,": "In thermodynamics,",
    "work (usaha)": "work (mechanical energy transfer)",
    "adalah energi yang berpindah akibat adanya gaya yang menyebabkan perpindahan batas sistem.": "is energy transferred when a force causes displacement of a system boundary.",
    "Salah satu contoh dapat dilihat pada gas di dalam silinder yang memiliki piston. Ketika gas mengembang, gas memberikan gaya pada piston sehingga piston berpindah. Perpindahan piston tersebut menunjukkan bahwa gas melakukan usaha terhadap lingkungan.": "One example is a gas inside a cylinder with a piston. As the gas expands, it exerts a force on the piston, causing it to move. This displacement shows that the gas does work on its surroundings.",
    "W = usaha": "W = work",
    "P = tekanan": "P = pressure",
    "ΔV = perubahan volume": "ΔV = volume change",
    "Perubahan volume dinyatakan sebagai": "The change in volume is expressed as",
    ". Pada proses ekspansi, volume bertambah sehingga usaha yang dilakukan gas bernilai positif. Pada kompresi, volume berkurang sehingga usaha oleh gas bernilai negatif.": ". During expansion, volume increases, so the work done by the gas is positive. During compression, volume decreases, so the work done by the gas is negative.",
    "Secara umum, work dalam proses termodinamika dapat dituliskan sebagai": "In general, thermodynamic work can be written as",
    ". Pada diagram P–V, besar usaha dapat dipahami sebagai luas daerah di bawah kurva.": ". On a P–V diagram, the work is represented by the area under the curve.",
    "B. Energi Dalam": "B. Internal Energy",
    "Internal energy (energi dalam)": "Internal energy (microscopic stored energy)",
    "adalah total energi mikroskopis yang tersimpan di dalam suatu sistem. Energi ini berkaitan dengan gerak dan interaksi partikel-partikel penyusun sistem.": "is the total microscopic energy stored in a system. It is associated with the motion and interactions of the system's constituent particles.",
    "Energi dalam dilambangkan dengan": "Internal energy is denoted by",
    ", sedangkan perubahan energi dalam dinyatakan sebagai:": ", while its change is expressed as:",
    "Untuk gas ideal, energi dalam terutama bergantung pada temperatur. Ketika temperatur berubah, energi dalam sistem juga dapat berubah.": "For an ideal gas, internal energy depends primarily on temperature. When the temperature changes, the system's internal energy can also change.",
    "Energi dalam merupakan": "Internal energy is a",
    "sifat keadaan sistem": "state property of the system",
    ". Artinya, perubahan energi dalam bergantung pada keadaan awal dan keadaan akhir sistem.": ". This means that the change in internal energy depends on the initial and final states of the system.",
    "C. Kalor, Usaha, dan Energi Dalam": "C. Heat, Work, and Internal Energy",
    "Energi yang berpindah akibat kerja mekanis atau gaya yang menyebabkan perpindahan.": "Energy transferred through mechanical work or a force that causes displacement.",
    "Energi mikroskopis yang tersimpan di dalam sistem.": "Microscopic energy stored inside a system.",
    "bukan energi yang tersimpan di dalam sistem": "are not energy stored inside the system",
    ". Keduanya merupakan mekanisme perpindahan energi yang dapat menyebabkan perubahan energi dalam.": ". Both are mechanisms of energy transfer that can change internal energy.",
    "Hubungan Hukum I": "First Law Relation",
    "Usaha oleh Gas": "Work Done by a Gas",
    "Amati bagaimana ekspansi gas menggerakkan piston dan menghasilkan usaha mekanis.": "Observe how gas expansion moves the piston and produces mechanical work.",
    "Energi Masuk": "Energy Input",
    "Perpindahan piston": "Piston displacement",
