    "Suhu tetap selama proses. Perubahan volume mengubah tekanan. Kalor yang diterima sama dengan usaha yang dilakukan gas.": "Temperature remains constant throughout the process. Changing the volume changes the pressure. The heat absorbed equals the work done by the gas.",
